--  * The free-practice-exam claim is verified: the course page renders the "Bonus: Free Practice
--    Exams" card (cert-prep tree gate) and the portal has /practice-exams/microsoft/microsoft-md-102.
--  * hero_image_url is NOT set here (SQL cannot render one) — generate on prod post-deploy.

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);

INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Microsoft Endpoint Administrator (MD-102) Certification in Singapore: WSQ Funding and Free Practice Exams', 'microsoft-endpoint-administrator-md-102-certification-singapore', 'Hybrid work turned every IT team into a device-management team, and Microsoft''s MD-102 is the certification that proves you can run a modern endpoint fleet. Here is why the Endpoint Administrator Associate credential is worth it, how WSQ funding brings the 5-day course down to $975 nett for eligible Singaporeans, and how to try a free MD-102 practice exam before you commit.', '<p>Every company that handed out laptops during the hybrid-work shift now has the same problem: hundreds of Windows devices, personal phones touching corporate data, and one small IT team expected to keep it all patched, compliant and secure. The person who solves that problem is the <strong>endpoint administrator</strong> — and Microsoft''s <strong>MD-102: Endpoint Administrator</strong> exam is the certification that proves you can do it. In this guide we cover why the certification is worth your time, how the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-endpoint-administrator-associate-md-102.html">WSQ Microsoft Certified Endpoint Administrator Associate (MD-102) course</a> gets you there with up to 70% funding, and how to test yourself first with a free MD-102 practice exam.</p> <h2>Why endpoint administration is a career-safe skill</h2> <p>Endpoint administration sits at the intersection of the two things organisations refuse to cut budget on: <strong>productivity</strong> (people must be able to work from any device, anywhere) and <strong>security</strong> (none of those devices may become the breach headline). Concretely, the role owns:</p> <ul> <li><strong>Device management at scale</strong> — enrolling, configuring and updating fleets of Windows machines and mobile devices through Microsoft Intune, rather than touching them one by one.</li> <li><strong>Identity and access</strong> — managing users and devices in Microsoft Entra ID so the right people reach the right resources, with Conditional Access keeping everyone else out.</li> <li><strong>Compliance and protection</strong> — enforcing device-compliance policies, protecting corporate data on personal devices, and running Microsoft Defender for Endpoint.</li> </ul> <p>These skills map directly to job titles Singapore employers are actively hiring for: IT support engineer, desktop engineer, systems administrator, modern-workplace engineer and endpoint administrator. And because Intune and Entra ID are subscription products that change monthly, employers strongly prefer candidates with a current, verifiable credential over "used SCCM years ago" on a CV.</p> <h2>What the MD-102 certification actually proves</h2> <p>Passing MD-102 earns you the <strong>Microsoft 365 Certified: Endpoint Administrator Associate</strong> badge. It replaced the older MD-100/MD-101 pair, so it is the single exam route into modern Microsoft device management. The exam tests four skill areas: deploying Windows clients, managing identity and compliance, managing/maintaining devices, and managing applications. It is an intermediate-level exam — you are expected to know your way around Intune, Entra ID and Windows configuration, which is exactly the gap a structured course closes.</p> <h2>Why take an instructor-led course instead of self-studying</h2> <p>You can self-study MD-102 from Microsoft Learn — the content is free. What self-study does not give you is a lab environment that mirrors a real tenant, an instructor who has seen every way an Intune enrolment can fail, and the discipline of five structured days. The <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-endpoint-administrator-associate-md-102.html">WSQ MD-102 course</a> runs <strong>5 days (40 hours)</strong> of hands-on training as an <strong>Authorised Microsoft Learning Partner (Org ID: 5238476)</strong>, and being a WSQ course it carries something self-study never will: <strong>SkillsFuture Singapore course-fee funding</strong> plus a WSQ Statement of Attainment on top of your exam preparation.</p> <p>Across the five days you will work through the full endpoint lifecycle:</p> <ul> <li><strong>The enterprise desktop and Windows editions</strong> — deployment options and servicing channels.</li> <li><strong>Microsoft Entra ID</strong> — managing identities, groups and device authentication.</li> <li><strong>Device enrolment</strong> — bringing devices under management with Microsoft Intune and Configuration Manager.</li> <li><strong>Device and user profiles</strong> — building, deploying and monitoring configuration profiles.</li> <li><strong>Application management</strong> — deploying and updating apps, plus mobile application management (MAM) for BYOD.</li> <li><strong>Identity protection and access</strong> — Conditional Access and organisational access done properly.</li> <li><strong>Compliance and reporting</strong> — device-compliance policies, inventory and compliance reports.</li> <li><strong>Endpoint security</strong> — device data protection and Microsoft Defender for Endpoint.</li> </ul> <p>After the course, you register for the official MD-102 exam at a Pearson VUE test centre to earn the Microsoft badge.</p> <h2>How much it costs — and how little you actually pay</h2> <p>The full course fee is <strong>$2,500 before GST</strong>. Because this is a WSQ course, SkillsFuture Singapore funds a large share of it for Singaporeans and PRs:</p> <table> <tr><th>Who you are</th><th>Funding level</th><th>Nett fee (incl. GST)</th></tr> <tr><td>Singaporean / PR, age 21+</td><td>50% baseline funding</td><td><strong>$1,475</strong></td></tr> <tr><td>Singaporean age 40+ (MCES) or SME-sponsored</td><td>70% funding</td><td><strong>$975</strong></td></tr> </table> <p>On top of the base funding, four schemes can shrink the out-of-pocket amount further:</p> <ul> <li><strong>SkillsFuture Credit</strong> — eligible Singaporeans can offset the nett fee with their SkillsFuture Credit balance (note: the $4,000 Additional SFC for mid-career support cannot be used for this course).</li> <li><strong>SFEC</strong> — Singapore-registered companies with SkillsFuture Enterprise Credit can use it to cover out-of-pocket costs when sponsoring staff.</li> <li><strong>PSEA</strong> — eligible Singaporeans can pay the balance from their Post-Secondary Education Account.</li> <li><strong>UTAP</strong> — NTUC members may claim 50% of the unfunded fee, capped at $250/year (or $500/year for members aged 40 and above). UTAP support is course-specific and subject to NTUC approval.</li> </ul> <p>In practice, a 40-plus Singaporean using SkillsFuture Credit can bring a $2,725 course down to a few hundred dollars — or zero. The exact eligibility checks and application steps are listed on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-endpoint-administrator-associate-md-102.html">course page</a>.</p> <h2>Try before you commit: free MD-102 practice questions</h2> <p>Not sure where you stand? Our <a href="https://exams.tertiaryinfotech.com/">Practice Exam Portal</a> at exams.tertiaryinfotech.com has a dedicated <a href="https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-md-102">MD-102 practice exam</a>, and you can <strong>try 10 questions free — no credit card, retake the teaser as often as you like</strong>. It is the fastest way to find out whether you are ready to book the official exam or whether the 5-day course should come first.</p> <p>Course participants get the full experience as an included bonus: a realistic <strong>Practice Mode</strong> that explains each answer, a timed <strong>Exam Mode</strong> that simulates test-centre pressure, and <strong>unlimited retakes</strong> until the real exam. Walking into Pearson VUE having already passed the exam five times in simulation changes everything about exam day.</p> <h2>Frequently asked questions</h2> <div class="mmd-faq"> <details class="mmd-faq-item"><summary class="mmd-faq-q">Who should take the MD-102 course?</summary><div class="mmd-faq-a"><p>IT support engineers, desktop and systems administrators, and anyone moving into modern workplace or endpoint management roles. It is an intermediate course — basic familiarity with Windows administration and Microsoft 365 helps, and the prerequisites are listed on the course page.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">Is the official Microsoft exam included in the course fee?</summary><div class="mmd-faq-a"><p>The course prepares you for the exam and includes unlimited practice exams on our portal, but the official MD-102 exam is registered separately at a Pearson VUE test centre. As an Authorised Microsoft Learning Partner we will point you to the current exam registration process in class.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">How much funding can I get?</summary><div class="mmd-faq-a"><p>Singaporeans and PRs aged 21+ get 50% SkillsFuture funding (nett $1,475 incl. GST). Singaporeans aged 40+ and SME-sponsored staff get 70% (nett $975). SkillsFuture Credit, SFEC, PSEA and UTAP can reduce the payable amount further — see the funding section on the <a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-endpoint-administrator-associate-md-102.html">course page</a> for eligibility.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">What is the difference between MD-102 and the old MD-100/MD-101?</summary><div class="mmd-faq-a"><p>Microsoft consolidated the two older Modern Desktop Administrator exams into the single MD-102 Endpoint Administrator exam. If you were planning the old route, MD-102 is now the only exam you need for the Endpoint Administrator Associate certification.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">Are the practice exams really free?</summary><div class="mmd-faq-a"><p>Anyone can try a 10-question teaser on the MD-102 practice exam free, with no credit card and unlimited teaser retakes. Full access — the complete question bank in Practice Mode and timed Exam Mode with unlimited retakes — is included when you register for the course.</p></div></details> <details class="mmd-faq-item"><summary class="mmd-faq-q">Do I get a certificate from the course itself?</summary><div class="mmd-faq-a"><p>Yes — completing the WSQ course and assessment earns you a WSQ Statement of Attainment from SkillsFuture Singapore, independent of the Microsoft certification you earn by passing MD-102 at Pearson VUE. Most learners leave with both.</p></div></details> </div> <h2>Next steps</h2> <ol> <li><a href="https://exams.tertiaryinfotech.com/practice-exams/microsoft/microsoft-md-102">Take the free 10-question MD-102 practice teaser</a> to benchmark where you stand today.</li> <li>Check your funding eligibility — Singaporeans aged 40+ pay just <strong>$975 nett</strong> before SkillsFuture Credit.</li> <li><a href="https://www.tertiarycourses.com.sg/wsq-microsoft-certified-endpoint-administrator-associate-md-102.html">Register for the WSQ Microsoft Certified Endpoint Administrator Associate (MD-102) course</a> and pick your preferred class date.</li> <li>After the 5-day course, drill the full practice exam until you pass consistently, then book the official exam at Pearson VUE.</li> </ol> <p><em>Fees and funding percentages are accurate at the time of writing — always check the live course page for the latest figures and class dates.</em></p>', 'Tertiary Infotech Academy', 1, '2025-11-14', 'TGS-2024042603', 'TGS-2024042603', 'MD-102 Endpoint Administrator Course Singapore | WSQ Funding', 'Become a Microsoft Certified Endpoint Administrator (MD-102) in Singapore. 5-day WSQ course with up to 70% funding, SkillsFuture Credit, and free MD-102 practice exams.', 'md-102 course singapore, microsoft endpoint administrator certification, md-102 exam prep, wsq microsoft course, intune training singapore, skillsfuture microsoft certification, md-102 practice exam, microsoft 365 endpoint administrator associate', '2025-11-14 09:00:00', '2025-11-14 09:00:00' FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'microsoft-endpoint-administrator-md-102-certification-singapore');

-- Tags (core Magento tag vocabulary; status 1 = approved)
INSERT INTO `tag` (`name`, `status`) SELECT 'Microsoft', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'Microsoft');
INSERT INTO `tag` (`name`, `status`) SELECT 'MD-102', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'MD-102');
INSERT INTO `tag` (`name`, `status`) SELECT 'Intune', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'Intune');
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'WSQ');

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'microsoft-endpoint-administrator-md-102-certification-singapore');

INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @post_id, `tag_id` FROM `tag` WHERE @post_id IS NOT NULL AND `name` IN ('Microsoft', 'MD-102', 'Intune', 'WSQ');

-- Seed the like count so the post does not ship showing "0 Likes" (same `likes < 100`
-- idempotency guard as migrations 868/869 — only raises into the band, never overwrites
-- a genuine count that has grown past it).
UPDATE `mmd_blog_post` SET `likes` = 138 WHERE `url_key` = 'microsoft-endpoint-administrator-md-102-certification-singapore' AND `likes` < 100;
